# Test double for hdd_run.sh (kit v4, v5, v6; v10's page-event log; v13's cache-drop line and version): answers the three RPC calls the kit makes. Not monerod; for the kit's tests only.
# Height starts at 3,106,401 and, after a FAKE_WARM s warm-up, grows by one block every FAKE_STEP s.
# FAKE_STATE: file where each served height is written; with --offline the fake serves that height, unchanged
#   (the kit's post-check after a death).
# FAKE_DIE_AFTER: die (SIGKILL to itself) that many seconds after start, if FAKE_DIE_LEVEL is unset or equals MEM_MAX;
#   with FAKE_DIE_OOM=1 it first marks oom 1 / oom_kill 1 in the fake scope's memory.events (under FAKE_CG_ROOT),
#   standing in for the kernel. Never with --offline.
# FAKE_ALLOC_MB_S: allocate and touch this many MB of anonymous memory per second, up to FAKE_ALLOC_MAX_MB
#   (default 4096): for the real-cgroup test, where the kernel does the OOM-kill.
# FAKE_ARGS_LOG: file to which each start appends its arguments.
# v13: FAKE_VERSION: the line --version prints (default "Monero 'Fake' (v0.0.0.0-fake-kit-test)"). FAKE_CDROP=on|off|none: the
#   startup line written to --log-file: "LMDB page cache drop: on", "... off (<FAKE_CDROP_REASON>)" (default reason "no
#   cachestat available"), or none (default).
import glob, http.server, json, os, re, signal, sys, threading, time
args = sys.argv[1:]
if "--version" in args:
    print(os.environ.get("FAKE_VERSION", "Monero 'Fake' (v0.0.0.0-fake-kit-test)")); sys.exit(0)
if os.environ.get("FAKE_ARGS_LOG"):
    with open(os.environ["FAKE_ARGS_LOG"], "a") as f: f.write(" ".join(args) + "\n")
port = int(args[args.index("--rpc-bind-port") + 1])
offline = "--offline" in args
WARM = float(os.environ.get("FAKE_WARM", "3")); STEP = float(os.environ.get("FAKE_STEP", "0.1"))
STATE = os.environ.get("FAKE_STATE", "")
t0 = time.time()
fixed = None
if offline:
    try: fixed = int(open(STATE).read().strip())
    except Exception: fixed = 3106401
def height():
    if fixed is not None: return fixed
    el = time.time() - t0
    h = 3106401 + (0 if el < WARM else int((el - WARM) / STEP) + 1)
    if STATE:
        with open(STATE + ".tmp", "w") as f: f.write(str(h))
        os.replace(STATE + ".tmp", STATE)
