def die():
    if os.environ.get("FAKE_DIE_OOM") == "1":
        for e in glob.glob(os.path.join(os.environ.get("FAKE_CG_ROOT", "/nonexistent"), "system.slice", "*.scope", "memory.events")):
            s = open(e).read(); s = re.sub(r"(?m)^oom 0$", "oom 1", s); s = re.sub(r"(?m)^oom_kill 0$", "oom_kill 1", s)
            open(e, "w").write(s)
    os.kill(os.getpid(), signal.SIGKILL)
lvl = os.environ.get("FAKE_DIE_LEVEL")
if not offline and os.environ.get("FAKE_DIE_AFTER") and (lvl is None or lvl == os.environ.get("MEM_MAX")):
    threading.Timer(float(os.environ["FAKE_DIE_AFTER"]), die).start()
