# v5: FAKE_WARMUP_LINE is written to the --log-file at start, as monerod .5 logs its warm-up; FAKE_STARTUP_S (default 1)
# is the time before RPC answers.
# v6: with FAKE_WARMUP_BG=<s> as well, it behaves as .6-prep: a start line ("Index warm-up: reading ... in the background")
# at launch, and FAKE_WARMUP_LINE (the completion line) <s> seconds later. FAKE_WARMUP_STOP=1: a "stopped" line instead of
# the completion line. Log timestamps are the local time now, as monerod writes them.
def stamp(): t = time.time(); return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(t)) + ".%03d" % (int(t * 1000) % 1000)
def wlog(msg):
    with open(args[args.index("--log-file") + 1], "a") as lf:
        lf.write(stamp() + "\t1\tINFO\tglobal\tsrc/blockchain_db/lmdb/db_lmdb.cpp:3038\t" + msg + "\n")
